const PISTES = {

  /* ── Unitat 1 · Matrius ──────────────────────────────────────────────── */
  'u1/12': 'La primera operació es fa directa: primer fas la resta i després multipliques per 2 tots els elements de la matriu resultant.<br>Per fer la segona operació, recomanem aplicar primer la <b>propietat distributiva</b> i agrupa els termes semblants, abans de calcular amb les matrius: així faràs menys càlculs amb matrius.<br>',
  'u1/13': 'Abans de multiplicar, mira la dimensió: una matriu fila 1×3 per una matriu columna 3×1 dona una matriu 1×1, és a dir, que té un sol element.<br>Per obtenir-lo, multiplica els elements que ocupen la mateixa posició i suma els tres productes. Els nombres que multipliquen (2, 5 i 3) pots deixar-los per al final: saps per què?',
  'u1/15': 'Comença per les dimensions, sense fer cap càlcul: el producte d\'una matriu 2×2 per una de 2×3 dona una matriu 2×3, i per poder sumar dues matrius han de tenir la mateixa dimensió.<br>Després, comprova-ho fent els càlculs: primer el producte, després els nombres que multipliquen i, finalment, la suma.',
  'u1/16': 'Dues matrius <b>commuten</b> quan <i>A · B</i> = <i>B · A</i>. Calcula els dos productes per separat i compara\'ls, element a element: n\'hi ha prou que un sol element sigui diferent per concloure que la igualtat no és certa.<br>Per a fer el segon apartat, calcula els dos membres de la igualtat per separat: a l\'esquerra, suma primer <i>B</i> + <i>C</i> i multiplica després per <i>A</i>; a la dreta, fes <i>AB</i> i <i>AC</i> i suma els resultats. Es compleix la igualtat, en aquest cas?',
  'u1/17': 'Podem pensar que una matriu és com un full de càlcul, o també com si fos una taula de doble entrada.<br>Per tant, has de decidir què posaràs a les files i què a les columnes: per exemple, els dies a les files i les línies a les columnes. Mantén el mateix criteri fins al final.<br>Així, l\'element de la fila <i>i</i> i la columna <i>j</i> és el nombre d\'autobusos de la línia <i>j</i> el dia <i>i</i>: és la posició de cada element la que li dona el significat.',
  'u1/42': 'Recorda què ha de complir cada tipus de matriu:<br>- <b>Matriu fila</b>: només té una fila.<br>- <b>Matriu quadrada</b>: té tantes files com columnes.<br>- <b>Matriu diagonal</b>: és quadrada i fora de la diagonal principal només hi ha zeros.<br>- <b>Matriu triangular inferior</b>: té zeros per sobre de la diagonal principal.<br>',
  'u1/49': 'Abans de multiplicar, escriu la dimensió de cada matriu. Un producte només és possible si el nombre de columnes de la primera coincideix amb el nombre de files de la segona.<br><b>Atenció</b>: que es pugui fer <i>AB</i> no vol dir que es pugui fer <i>BA</i>.',
  'u1/69': 'Que el producte compleixi la <b>propietat commutativa</b> vol dir que <i>A · B</i> = <i>B · A</i>. Calcula els dos productes per separat (sempre fila de la primera per columna de la segona) i compara\'ls element a element.<br>Si només un element és diferent, ja pots afirmar que no la compleix.',
  'u1/81': 'Calcula <i>A</i>², <i>A</i>³ i <i>A</i>⁴ i fixa\'t en quin element de la matriu canvia i de quina manera: això et permet deduir una expressió per a <i>Aⁿ</i> que depèn de <i>n</i>.<br>Un cop la tinguis, substitueix <i>n</i> = 22 i <i>n</i> = 2 i opera.',
  'u1/85': 'Una matriu és <b>nilpotent de grau</b> <i>k</i> quan <i>Aᵏ</i> és la matriu nul·la i és el primer exponent ho compleix.<br>Apartat a): calcula <i>A</i>² i comprova que no és la matriu nul·la; després calcula <i>A</i>³ = <i>A</i>²·<i>A</i>.<br>Apartat b): calcula <i>B</i>² en funció d\'<i>a</i> i <i>b</i>. Perquè <i>B</i> sigui nilpotent de grau 2, s\'han de complir alhora dues condicions:<br>1- <i>B</i>² és la matriu nul·la: això et dona una condició sobre <i>a</i> i <i>b</i>.<br>2- <i>B</i> no és la matriu nul·la.<br><br><b>Observació</b>: una matriu nul·la és una matriu on tots els elements són 0.',

  /* ── Unitat 2 · Determinants ─────────────────────────────────────────── */
  'u2/35': 'Un determinant 2×2 és el producte de la diagonal principal menys el de l\'altra diagonal. Per a |A + B| i |A − B|, fes primer la suma o la resta de les matrius i calcula el determinant després: no és el mateix que sumar o restar |A| i |B|.',
  'u2/36': 'Busca la matriu més senzilla possible: en una matriu diagonal, el determinant és el producte dels elements de la diagonal. Parteix de la matriu identitat i canvia-hi un sol element.',
  'u2/37': 'Aplica la regla de sempre, producte de la diagonal principal menys producte de l\'altra diagonal, també quan hi ha lletres. Després desenvolupa els productes i agrupa els termes semblants.',
  'u2/41': 'Fes servir la regla de Sarrus: tres productes en la direcció de la diagonal principal que sumen, i tres en la direcció de l\'altra diagonal que resten. Amb lletres, escriu els sis productes amb calma abans de simplificar.',
  'u2/44': 'Calcula el determinant deixant m i n com a lletres; si el desenvolupes per la fila que té un zero, t\'estalvies feina. Et quedarà una expressió amb m i n: iguala-la a zero i aïlla una lletra en funció de l\'altra.',
  'u2/79': 'El rang és l\'ordre del menor més gran que no val zero. Comença per un menor 2×2 no nul i orla\'l amb una fila i una columna més; si tots els menors 3×3 que el contenen valen zero, el rang es queda en 2.',
  'u2/80': 'Per arribar a rang 3, la fila nova no pot ser combinació de les altres dues: tria\'n una de senzilla i comprova que el determinant 3×3 no val zero. Per quedar-te en rang 2, fes que sigui combinació lineal de les files de A (per exemple, la seva suma).',
  'u2/83': 'Busca primer un menor d\'ordre 2 que no depengui del paràmetre i que no valgui zero: així ja saps que el rang és almenys 2. Després calcula els menors d\'ordre 3 que el contenen: el rang només baixa per als valors que els anul·len tots alhora.',
  'u2/87': 'Una matriu 2×2 que no és nul·la té rang 1 exactament quan el seu determinant val zero. Escriu el determinant en funció de a, iguala\'l a zero i resol l\'equació.',
  'u2/95': 'No cal que calculis cap inversa: multiplica cada matriu per cada candidata i mira quin producte dona la matriu identitat. Si vols anar més de pressa, compara abans els determinants: el de la inversa és l\'invers del de la matriu.',
  'u2/96': 'Aplica A⁻¹ = (1/|A|)·Adj(A)ᵗ: calcula el determinant (si fos zero, no hi hauria inversa), després la matriu d\'adjunts, transposa-la i divideix per |A|. Al final, comprova que A·A⁻¹ dona la identitat.',
  'u2/99': 'Una matriu és singular quan el seu determinant val zero: calcula\'l en funció de m, iguala\'l a zero i resol. Per a m = 2, substitueix el valor i calcula la inversa amb la matriu adjunta.',
  'u2/100': 'Calcula el determinant en funció de a i b i fixa\'t que el pots escriure com una identitat notable: així veuràs de seguida quan val zero. Per a l\'apartat b, substitueix els valors i calcula la inversa de la matriu 2×2.',

  /* ── Unitat 3 · Sistemes d'equacions ─────────────────────────────────── */
  'u3/38': 'Redueix cada sistema (substitució, reducció o Gauss) fins que vegis què passa: si surt una única solució, és compatible determinat; si una equació desapareix (0 = 0) i queden menys equacions que incògnites, és compatible indeterminat; si surt una igualtat impossible com 0 = 3, és incompatible.',
  'u3/39': 'La manera més segura d\'afegir una equació sense trencar la compatibilitat és fer-la combinació lineal de les que ja tens: suma-les, resta-les o multiplica-les per un nombre. Una altra opció: resol primer el sistema i inventa una equació que aquesta solució compleixi.',
  'u3/41': 'Multiplica cada fila de la matriu de coeficients per la columna d\'incògnites: cada fila dona una equació, i el terme independent és l\'element corresponent de la columna de la dreta. Fixa\'t bé en quines són les incògnites de cada sistema, que no sempre són x, y, z.',
  'u3/42': 'Separa cada sistema en tres parts: la matriu de coeficients (una fila per equació i una columna per incògnita), la columna de les incògnites i la columna dels termes independents. Si a una equació li falta una incògnita, el seu coeficient és 0.',
  'u3/43': 'Escriu la matriu ampliada i fes zeros per sota de la diagonal amb operacions entre files, columna a columna. Quan la tinguis escalonada, resol de baix a dalt. Si una fila es fa tota zero o surt 0 = k, atura\'t i pensa què vol dir.',
  'u3/55': 'Per a cada sistema, escriu la matriu de coeficients A i l\'ampliada A*, i calcula\'n els rangs. Si són diferents, és incompatible; si són iguals i coincideixen amb el nombre d\'incògnites, compatible determinat; si són iguals però més petits, compatible indeterminat.',
  'u3/56': 'Compara sempre tres nombres: Rang(A), Rang(A*) i el nombre d\'incògnites. Si A és quadrada, comença pel seu determinant: si no és zero, el rang ja és màxim. Vigila els sistemes amb més equacions que incògnites, perquè l\'ampliada hi pot tenir un rang més gran.',
  'u3/60': 'Calcula el determinant de la matriu de coeficients en funció de m i troba els valors que l\'anul·len. Per a la resta de valors, el sistema és compatible determinat; per a cadascun dels valors especials, substitueix-lo i estudia per separat els rangs de A i de A*.',
  'u3/64': 'Busca primer els valors d\'a que anul·len |A|: per als altres, el sistema és compatible determinat. Per als valors crítics, compara Rang(A) i Rang(A*). En el cas compatible indeterminat, elimina l\'equació que sobra i passa una incògnita a la dreta com a paràmetre.',
  'u3/66': 'a) Estudia |A| en funció de m i analitza a part els valors que l\'anul·len, comparant Rang(A) i Rang(A*). b) Abans de resoldre per a m = −1 i m = 2, mira a l\'apartat a quin tipus de sistema és en cada cas: així sabràs si has d\'esperar una solució única o infinites.',
  'u3/90': 'Anomena x, y, z el preu d\'una medalla d\'or, de plata i de bronze. Cada comanda de la taula et dona una equació: quantitat de cada medalla per preu, tot sumat, igual al total de la comanda. Resol el sistema de tres equacions pel mètode de Gauss.',
  'u3/92': 'Planteja una equació per a cada compra: nombre d\'accions per preu, tot sumat, igual al que es paga. Tindràs dues equacions i tres incògnites: estudia\'n els rangs per saber quantes solucions hi ha, i després fes servir que els preus són enters entre 1 i 12 € per trobar la bona.',
  'u3/94': 'Anomena x, y, z els alumnes d\'ESO, Batxillerat i Cicles i tradueix cada frase en una equació: «excedeix en 100» vol dir que una quantitat és igual a l\'altra més 100, i els percentatges s\'escriuen com a decimals (40 % = 0,4). No t\'oblidis de l\'equació del total d\'estudiants.',
  'u3/100': 'Llegeix amb calma què cal per produir cada producte i escriu una equació per a cada empresa amb les unitats p₁, p₂ i p₃. Després hi incorpores les demandes i resols el sistema de tres equacions que en surt, per Cramer o per Gauss.',

  /* ── Unitat 5 · Rectes i plans en l'espai ────────────────────────────── */
  'u5/43': 'Amb un punt i un vector director ja ho tens tot. La vectorial és punt + t·vector; les paramètriques surten de separar-la per coordenades; i la contínua, d\'aïllar t a cada paramètrica i igualar les tres expressions.',
  'u5/45': 'Cada valor del paràmetre t et dona un punt de la recta. Tria\'n tres de fàcils (t = 0, t = 1, t = −1) i substitueix-los a l\'equació.',
  'u5/46': 'Comença per la vectorial (punt + t·vector) i passa d\'una forma a l\'altra: paramètriques, contínua i, finalment, les implícites, que surten d\'igualar dues a dues les fraccions de la contínua i treure denominadors.',
  'u5/47': 'Et falta el vector director: és el vector que va d\'un punt a l\'altre, AB = B − A. Amb A i aquest vector, escriu totes les formes de l\'equació.',
  'u5/49': 'Si la recta que busques és paral·lela a r, té el mateix vector director que r. Treu-lo de l\'equació de r (si r ve donada per dos plans, resol-la passant-la a paramètriques) i fes-lo servir amb el punt P.',
  'u5/53': 'Un pla queda determinat per un punt i dos vectors directors (que no siguin paral·lels), o per un punt i un vector normal. a) Fes vectors amb els tres punts. b) Ja ho tens tot. c) El vector normal et dona els coeficients A, B i C de l\'equació general; D surt d\'imposar que hi passi el punt.',
  'u5/54': 'Que el pla passi pel punt vol dir que les coordenades del punt compleixen l\'equació del pla. Substitueix-les i aïlla m.',
  'u5/55': 'Dos plans paral·lels tenen el mateix vector normal, és a dir, els mateixos coeficients de x, y i z. Només canvia el terme independent, que surt d\'imposar que el pla passi pel punt P.',
  'u5/56': 'Si el pla és perpendicular a la recta, el vector director de la recta fa de vector normal del pla. Escriu l\'equació general amb aquests coeficients i troba el terme independent imposant que hi passi el punt.',
  'u5/59': 'Cada eix té dues coordenades nul·les: per a l\'eix X, fes y = 0 i z = 0 a l\'equació i aïlla x; el mateix per als altres eixos. Si en algun cas no pots aïllar la coordenada (surt una contradicció), el pla no talla aquell eix.',
  'u5/63': 'Tres punts estan alineats si els vectors AB i AC són proporcionals. Calcula\'ls, planteja la proporcionalitat de les coordenades i resol-la per trobar a.',
  'u5/66': 'a) Fes dos vectors amb els tres punts i escriu el pla amb un determinant igualat a zero. b) Els quatre punts són coplanaris quan D pertany al pla ABC: substitueix les coordenades de D a l\'equació i aïlla k.',
  'u5/71': 'Per a cada parella, pren un punt i el vector director de cada recta. Compara els rangs de la matriu dels dos vectors directors i de la matriu que també inclou el vector que uneix els dos punts: així distingeixes si es tallen, són paral·leles, coincideixen o es creuen.',
  'u5/72': 'Primer comprova que els vectors directors no són proporcionals i que les rectes són coplanàries (el vector entre els dos punts depèn dels altres dos). Si es tallen, iguala les paramètriques coordenada a coordenada i resol el sistema en λ i μ.',
  'u5/73': 'Estudia els rangs amb els vectors directors i el vector PQ per veure si són secants. Si ho són, el pla que les conté passa per un punt de qualsevol de les dues rectes i té com a vectors directors els de les dues rectes.',
  'u5/74': 'Escriu la recta com a dues equacions implícites i ajunta-les amb l\'equació del pla: tens un sistema de tres equacions. Compara el rang de la matriu de coeficients amb el de l\'ampliada per decidir si es tallen, són paral·lels o la recta és continguda al pla.',
  'u5/76': 'Passa els dos plans a equació general i estudia el sistema que formen: si els coeficients de x, y, z són proporcionals, els plans són paral·lels o coincidents (depèn del terme independent); si no, es tallen en una recta.',
  'u5/77': 'Tres plans formen un sistema de tres equacions. Calcula el rang de la matriu de coeficients i el de l\'ampliada: si tots dos valen 3, es tallen en un punt; si valen 2, en una recta; i si són diferents, no tenen cap punt comú als tres.',
  'u5/79': 'Si es tallen, les rectes són coplanàries: el determinant format pels dos vectors directors i el vector que uneix un punt de cada recta ha de valer zero. Planteja\'l en funció de m, iguala\'l a zero i comprova que els vectors directors no són proporcionals.',
  'u5/80': 'Perquè siguin paral·leles, els vectors directors han de ser proporcionals: d\'aquí surt m. Comprova també que no siguin la mateixa recta (el vector entre un punt de cada una no ha de ser proporcional). El pla que les conté té com a vectors el director i aquest vector PQ.',
  'u5/81': 'Troba un punt i un vector director de cada recta (la primera, resolent el sistema de dos plans). Després estudia els rangs de la matriu dels vectors directors i de la que també inclou PQ, separant els valors de m que fan canviar aquests rangs.',
  'u5/84': 'Ajunta les dues equacions de la recta amb la del pla en un sistema de tres equacions. El determinant de la matriu de coeficients depèn de a: on no s\'anul·la es tallen en un punt; quan s\'anul·la, mira l\'ampliada, que depèn de b, per decidir si la recta és paral·lela o continguda al pla.',
  'u5/85': 'Tot depèn dels vectors normals dels dos plans. a) Paral·lels: vectors normals proporcionals. b) Perpendiculars: vectors normals perpendiculars, és a dir, producte escalar igual a zero.',

  /* ── Unitat 6 · Angles i distàncies a l'espai ────────────────────────── */
  'u6/74': 'Primer troba la projecció de P sobre la recta: el pla perpendicular a r que passa per P (el vector director de r en fa de vector normal) talla r en un punt Q. Aquest Q és el punt mitjà entre P i el simètric P′, o sigui que P′ = 2Q − P.',
  'u6/76': 'Traça la recta perpendicular al pla que passa per P (el vector normal del pla en fa de vector director) i troba el punt Q on talla el pla. Aquest Q és el punt mitjà entre P i el seu simètric: P′ = 2Q − P.',
  'u6/86': 'Aplica la fórmula de la distància d\'un punt a un pla: substitueix les coordenades del punt a l\'equació del pla, pren el valor absolut del resultat i divideix-lo pel mòdul del vector normal, √(A² + B² + C²).',
  'u6/88': 'Escriu el punt genèric de la recta en paramètriques, en funció d\'un paràmetre, i imposa que la seva distància al pla sigui √6. Com que la fórmula porta un valor absolut, l\'equació |…| = k et donarà dues solucions.',
  'u6/90': 'El punt del pla més proper a A és la projecció ortogonal de A: traça la recta perpendicular al pla que passa per A i troba on el talla. La distància la pots calcular amb la fórmula de punt a pla, o com la distància entre A i aquest punt.',
  'u6/92': 'Escriu el punt genèric de la recta en funció del paràmetre i aplica-li la fórmula de la distància a un pla, igualada a 1/3. El valor absolut et donarà dues equacions i, per tant, dos punts.',
  'u6/97': 'Estudia primer la posició relativa: si la recta talla el pla, la distància és 0. Si és paral·lela (el vector director és perpendicular al vector normal del pla), agafa qualsevol punt de la recta i calcula\'n la distància al pla.',
  'u6/115': 'Escriu el punt genèric de la recta en funció del paràmetre i iguala les seves distàncies als dos plans. Com que hi ha valors absoluts, en surten dues equacions (una per a cada signe) i, per tant, dos punts.',
  'u6/139': 'a) El vector normal del pla fa de vector director de la recta perpendicular. b) Substitueix les paramètriques de la recta a l\'equació del pla per trobar el punt de tall. c) La distància de P al pla és la distància de P a aquest punt, o bé la de la fórmula de punt a pla.',

  /* ── Unitat 7 · Límits i continuïtat ─────────────────────────────────── */
  'u7/40': 'En total, hauràs d\'obtenir dues equacions. Cada equació s\'obté igualant un límit per l\'esquerra amb un límit per la dreta.<br>Finalment, has de resoldre el sistema d\'equacions resultant, per trobar els valors d\'<i>a</i> i de <i>b</i>.',
  'u7/43': 'Defineix g(x) = f(x) − 1 i troba dos valors <i>a</i> i <i>b</i> tals que <i>f(a)</i> i <i>f(b)</i> tinguin signe contrari.<br>Podràs aplicar Bolzano perquè la funció <i>f</i> és contínua a tot ℝ - ja que és suma d\'una exponencial i d\'una polinòmica - i per tant <i>g</i> també és contínua a tot ℝ.',
  'u7/44': 'Estudia, per a cada gràfica, dos límits per separat: quan (x → +∞) i quan (x → −∞).<br>Has d\'observar si la corba s\'apropa a una alçada fixa (llavors tenim una asímptota horitzontal), o bé puja o baixa sense parar, o bé no s\'estabilitza.<br><b>Atenció</b>: no fa falta calcular res, només cal llegir el dibuix.',
  'u7/45': 'Quan <i>x</i> es fa molt i molt gran, has de decidir quin terme «guanya», és a dir, quin creix més de pressa.<br>Una exponencial (de base més gran que 1) sempre creix més de pressa que qualsevol polinomi, a la llarga.',
  'u7/46': '<b>Compara</b> el grau del numerador amb el grau del denominador:<br>- Si els graus són iguals, el límit és el quocient dels coeficients dels termes de grau més alt.<br>- Si el numerador té grau superior al denominador, el límit <b>no és finit</b>.<br>- Si el numerador té grau inferior al denominador, el límit <b>sempre</b> és <i>0</i>.<br><br>Atenció: en cas que el límit no sigui finit, pensa bé si és −∞ o +∞.',
  'u7/47': '- Si el límit és finit i és un nombre diferent de <i>0</i>, prova amb una funció racional adequada.<br>- Si el límit és infinit, pots provar amb un quocient de funcions, per exemple amb dos polinomis adequats.<br>- Si el límit és <i>0</i>, fixa\'t que si divideixes per exemple 3 entre qualsevol polinomi de grau 2, et funcionarà: saps per què funciona?',
  'u7/48': 'En cada cas, recorda que has de comparar els graus dels polinomis numerador i denominador.',
  'u7/66': 'Per a cada punt que et demanen, mira si la gràfica s\'acosta a la mateixa alçada pel costat esquerre i pel costat dret.<br>Si no coincideixen, dona els dos límits laterals per separat, en lloc d\'un únic valor.',
  'u7/68': 'Fes el mateix que amb la <i>f</i>: a cada punt marcat, comprova els límits laterals.<br>En el cas dels límits quan <i>x</i> → -∞ i quan <i>x</i> → +∞, has de fixar-te cap a on va la corba en els extrems de la gràfica: si puja, si baixa o si s\'estabilitza a una certa alçada.',
  'u7/70': 'Comprova per quin motiu √(<i>x</i>²+1) no és mai 0. Això et permet deduir que la funció és contínua a tot ℝ.<br>En aquests casos on la funció és contínua, és ben senzill calcular els límits, perquè només has de substituir el valor de <i>x</i> en cada cas.',
  'u7/76': 'Si en substituir obtens la <b>indeterminació</b> 0/0, això vol dir que el numerador i el denominador tenen un factor comú:<br>- Factoritza el numerador i també el denominador (potser traient factor comú, o bé fent servir la regla de Ruffini).<br>- Simplifica l\'expressió i torna a substituir, a veure si ja desapareix la indeterminació 0/0.',
  'u7/88': 'La funció és <b>definida a trossos</b>.<br>A <i>x</i> = −1 i a <i>x</i> = 3, calcula per separat el límit amb l\'expressió que val a l\'esquerra del punt i el límit amb la que val a la dreta.<br>Per a <i>x</i> → +∞, fixa\'t només en el tros de la definició que val quan <i>x</i> pren valors tant grans com vulguem.',
  'u7/90': 'La funció és <b>definida a trossos</b>.<br>Per a cadascun dels 4 punts de canvi, identifica quin tros s\'aplica a cada costat i calcula els dos límits laterals, per separat.<br>Per a <i>x</i> → -∞, fixa\'t només en el tros de la definició que cal tenir en compte.<br>Per a <i>x</i> → +∞, fixa\'t només en el tros de la definició que cal tenir en compte.',
  'u7/92': 'Per a cada gràfica, en el punt indicat has de comparar tres coses: el límit per l\'esquerra, el límit per la dreta i el valor de la funció en aquell punt.<br>- Si les tres coincideixen, la funció és contínua.<br>- Si els dos límits laterals són diferents, hi ha una discontinuïtat <b>de salt</b>.<br>- Si els dos límits laterals coincideixen entre ells però no amb el valor de la funció (o la funció no hi està definida), la discontinuïtat és <b>evitable</b>.<br>- Si algun dels límits laterals no és finit, la discontinuïtat és <b>de salt infinit</b>.',
  'u7/93': 'Abans de res, troba el domini de cada funció: en un punt que no sigui del domini, la funció no pot ser contínua perquè la imatge d\'aquell punt no existeix.<br>Per trobar el domini d\'una funció, tingues en compte això:<br>- Una arrel necessita que el que hi ha a dins sigui ≥ 0.<br>- Un logaritme necessita que el que hi ha a dins sigui > 0.<br>- El valor absolut no té cap requeriment, quant al domini.',
  'u7/94': 'Busca els valors de <i>x</i> que anul·len el denominador: només en aquests punts pot haver-hi discontinuïtat (saps per què en la resta de punts és contínua la funció?).<br>Calcula el límit en cadascun dels punts que trobis que anul·len el denominador:<br>- Si el límit és una indeterminació 0/0 però finalment obtens un límit finit, llavors la discontinuïtat és <b>evitable</b>.<br>- Si el límit no és finit, la discontinuïtat és <b>de salt infinit</b>.',
  'u7/102': 'La funció és <b>definida a trossos</b>.<br>A <i>x</i> = −1 i a <i>x</i> = 2, calcula per separat el límit per l\'esquerra i el límit per la dreta, cadascun amb el tros de la definició que li correspon.<br>Recorda que un logaritme només existeix quan el seu argument és positiu. Per exemple, <i>log(3)</i> existeix, però <i>log(-3)</i> i <i>log(0)</i> no existeixen.<br>Per decidir si la funció és contínua, compara els límits laterals i el valor de la funció en aquell punt.',
  'u7/103': 'En cadascun dels punts on hi ha un canvi en la definició de la funció, has de calcular el límit per l\'esquerra i el límit per la dreta. Para atenció al tros on hi ha l\'exponencial.<br>A continuació, compara els límits laterals i el valor de la funció en aquell punt: això et dirà si hi ha continuïtat.',
  'u7/106': 'Fes el mateix que a l\'exercici 40: en cada punt de canvi de tros, el límit per l\'esquerra ha de ser igual al límit per la dreta (i igual al valor de la funció en aquell punt).<br>Cada punt et dona una equació.<br>Resol el sistema d\'equacions que obtinguis, i podràs trobar els valors que et demanen: <i>a</i> i <i>b</i>.',
  'u7/112': 'La funció és contínua a tot ℝ (el motiu: és suma d\'una exponencial i d\'una polinòmica), i per tant pots aplicar el teorema de Bolzano.<br>Ves provant valors enters de <i>x</i> fins que les imatges <i>f(x)</i> canviïn de signe: llavors, hauràs obtingut un interval inicial.<br>Després, has d\'anar buscant altres valors (per bisecció) fins que la longitud de l\'interval sigui 1/2 o inferior.',
  'u7/113': 'Un polinomi és continu a tot ℝ, i per tant pots aplicar el teorema de Bolzano: només necessites trobar dos valors on <i>f</i> canviï de signe.<br>L\'interval que et demanen ha de tenir longitud 2, així pots provar amb valors enters que estiguin separats dues unitats.<br>Com a <b>curiositat</b>: com que tots els coeficients del polinomi són positius, realment creus que pot tenir alguna arrel positiva? Per tant... és preferible provar amb valors negatius.',
  'u7/114': 'Comprova, en primer lloc, que <i>f(-3)</i> i <i>f(-2)</i> tenen signes diferents.<br>Després, aplica el mètode de la bisecció. Cada pas divideix la longitud de l\'interval per dos.<br>Per tant, la longitud dels intervals successius serà: 1; 0,5; 0,25; 0,125... i només necessites un pas extra. Entens el motiu?',
  'u7/120': 'Dues corbes es tallen quan les dues funcions valen el mateix, és a dir, quan la seva diferència s\'anul·la.<br>Per tant, cada apartat es resol seguint el mateix mètode: defineix <i>h(x)</i> com la resta de les dues funcions i aplica el teorema de Bolzano a la funció auxiliar <i>h(x)</i>.<br><br><b>Atenció</b>: si hi ha un logaritme, estudia abans quin és el seu domini.',

  /* ── Unitat 8 · Derivades ─────────────────────────────────── */
  'u8/21': 'L\'equació de la recta tangent és: y − f(<i>e</i>) = f ′ (<i>e</i>)·(x − <i>e</i>).<br>Per tant, hauràs de calcular f(<i>e</i>), i f ′ (<i>e</i>).',
  'u8/30': 'La taxa de variació mitjana (TVM) sempre implica fer una divisió. Pots pensar que és com la velocitat mitjana, on divideixes l\'increment de posició entre l\'increment de temps.<br>Calcula la TVM i no t\'has de sorprendre si obtens el mateix resultat numèric: això ocorre perquè <i>f</i> és una <b>funció lineal</b> (és a dir, és un polinomi de primer grau).',
  'u8/31': 'Fes el càlcul de la taxa de variació mitjana, en els tres casos.<br><b>Curiositat</b>: fixa\'t que, en cadascun dels casos, et donarà el pendent de la recta que correspon a aquella funció.',
  'u8/32': 'En primer lloc, calcula les taxes de variació mitjana: [1,6] i [1,4]. És com si ens anem acostant cada cop més a <i>x=1</i><br>Finalment, has de calcular <i>f \' (1)</i>, que és el límit si cada vegada t\'acostessis més a <i>x=1</i>',
  'u8/37': 'Fes servir la definició de derivada d\'una funció en un punt (consulta el llibre).<br>Substitueix els valors <i>f(a+h)</i> i <i>f(a)</i>.<br><b>Atenció</b>, sempre obtindràs una indeterminació 0/0. Has d\'aconseguir simplificar-ho per no tenir un 0/0, i poder obtenir el límit.',
  'u8/40': 'Per obtenir l\'equació d\'aquesta recta tangent, necessites calcular <i>f(2)</i>, i també <i>f ′ (2)</i>.<br>Per representar la paràbola, troba en primer lloc les coordenades del seu vèrtex i, en segon lloc, calcula els punts de tall de la paràbola amb els eixos de coordenades.',
  'u8/41': 'Sabem que el punt P és damunt de la corba, i per tant sabem que la imatge de <i>x=1</i> és <i>f(1)=2</i>.<br>A partir d\'aquí podràs trobar el valor del paràmetre <i>a</i>. Un cop el tinguis, pensa com obtenir el pendent de la recta tangent en <i>x = 1</i>.',
  'u8/46': 'Per trobar el punt de tangència, hauràs de resoldre <i>f(x) = 0</i>, perquè és on la corba talla amb l\'eix d\'abscisses.<br>Per obtenir el pendent de la recta tangent, en primer lloc calcula f \' (x). <br>Finalment, recorda que la recta <b>normal</b> és perpendicular a la recta tangent, i per tant el seu pendent és <i>−1/m</i> (on <i>m</i> és el pendent de la recta tangent).',
  'u8/54': 'Dues rectes són paral·leles quan tenen el mateix pendent, i el de la recta <i>y = 2x -123</i> es pot trobar directament.<br>Un cop hagis trobat el pendent <i>m</i>, resol l\'equació <i>f ′ (x) = m</i>. Trobaràs dues solucions: per a cada solució, calcula la seva imatge, i així finalment hauràs obtingut dos punts.',
  'u8/58': 'En primer lloc, calcula l\'equació de la recta tangent en el punt indicat.<br>Després, calcula els punts d\'intersecció de la recta amb els eixos de coordenades. Els dos punts són vèrtexs del triangle, i el tercer vèrtex és l\'origen de coordenades.<br>Finalment, recorda que l\'àrea del triangle es calcula multiplicant la base per altura, i dividint entre dos.',
  'u8/86': 'Estigues alerta perquè en alguns casos cal derivar una composició de funcions i, per tant, cal aplicar la regla de la cadena.',
  'u8/87': 'Has d\'aplicar la definició de derivada, deixant la x com a lletra: calcula el límit de [<i>f(x+h)</i> − <i>f(x)</i>]/<i>h</i>, quan <i>h</i> tendeix a <i>0</i>.',
  'u8/88': 'Has d\'aplicar la definició de derivada, deixant la x com a lletra: calcula el límit de [<i>f(x+h)</i> − <i>f(x)</i>]/<i>h</i>, quan <i>h</i> tendeix a <i>0</i>.',
  'u8/92': 'Recorda que √x=x^(1/2), i també que 1/x = x^(-1).',
  'u8/93': 'Pel primer apartat: abans de derivar, pots expressar-ho com una sola potència.<br>En general, has d\'aplicar la fórmula per a derivar un producte de funcions.<br>Atenció, en algun cas cal aplicar la regla de la cadena.',
  'u8/97': '<i>a)</i> Aplica la regla de la cadena.<br><i>b)</i> Aplica la regla de la cadena <b>dues vegades</b>.<br><i>c)</i> Aplica la definició de derivada d\'un quocient de funcions.<br><i>d)</i> En algun moment, apareixerà un <i>ln 2</i>.',


  /* ── Unitat 9 · Aplicacions de les derivades ─────────────────────────── */
  'u9/30': 'En total, hauràs d\'obtenir <b>tres</b> equacions.<br>- Equació 1 i equació 2: sabem que hi ha un extrem relatiu, i per tant <i>f \' (1) = 0</i> i que <i>f \' (2) = 0</i>.<br>- Equació 3: el fet que el punt <i>P</i> sigui damunt de la gràfica vol dir que <i>f(1)=6</i>.<br><br>Per acabar, hauràs de resoldre un sistema d\'equacions, amb tres equacions i tres incògnites.',
  'u9/34': 'Com que la funció és <b>definida a trossos</b>, els candidats a màxim i mínim són de tres tipus:<br>- Dins de cada tros: resol <i>f ′(x) = 0</i> amb la derivada d\'aquell tros i comprova que la solució cau dins d\'aquell tros.<br>- El punt on canvia la definició: la derivada hi pot no existir, i per això resoldre <i>f ′(x) = 0</i> no te\'l donaria.<br>- Els extrems de l\'interval.<br><br>Calcula la imatge <i>f(x)</i> de tots els candidats i compara-les.',
  'u9/39': 'Els extrems relatius només poden ser en punts on la derivada s\'anul·la, així que tot es redueix quantes arrels té <i>f ′(x)</i>.<br>En el cas d\'una recta, la funció <i>f</i> té grau 1. En el cas d\'una paràbola, la funció <i>f</i> té grau 2.<br>Finalment, pensa el cas general d\'un polinomi de grau <i>n</i>.<br><b>Atenció</b>: si <i>f</i> és un polinomi de grau <i>n</i>, <i>f ′</i> és un polinomi de grau <i>n − 1</i>, i un polinomi no pot tenir més arrels que el seu grau.',
  'u9/41': 'La gràfica que et donen és la de la derivada <i>y=f ′(x)</i>, no la de <i>y=f(x)</i>. Els extrems relatius de <i>f(X)</i> són els valors solució de l\'equació <i>f ′(x) = 0</i>, és a dir, on <b>la gràfica de f \'(x) talla l\'eix d\'abscisses</b>.<br>Per saber si un extrem relatiu és màxim o és mínim, estudia el signe de <i>f ′</i> a banda i banda:<br>- De positiu a negatiu: <i>f</i> passa de créixer a decréixer, i hi ha un màxim.<br>- De negatiu a positiu: <i>f</i> passa de decréixer a créixer, i hi ha un mínim.<br><br><b>Atenció</b>: hi ha un cas molt curiós: quan la gràfica de <i>f \'(x) </i> és tangent a l\'eix d\'abscisses, però no canvia de signe. Saps per què allà no hi ha extrem relatiu?',
  'u9/42': 'Per a cada funció, troba els seus punts crítics resolent l\'equació <i>f ′(x) = 0</i>.<br>A partir d\'aquests punts, obtindràs uns intervals.',
  'u9/44': 'Una manera senzilla és pensar amb un polinomi de segon grau, perquè la seva gràfica és una paràbola i en el vèrtex és on hi ha el màxim relatiu, o bé el mínim relatiu.<br>Per exemple, la paràbola <i>f(x) = (x − 3)²</i> té el vèrtex a <i>x = 3</i>, i és un mínim.<br>A partir d\'aquí, pensa quins exemples pots posar.',
  'u9/50': 'Troba els punts crítics resolent l\'equació <i>f ′(x) = 0</i>.<br>Per a cada solució que trobis, substitueix-la a la derivada segona <i>f ″(x)</i>.<br>- Si <i>f ″(a) > 0 </i> llavors la gràfica té concavitat positiva localment i per tant x=a és un mínim relatiu<br>- Si <i>f ″(a) < 0 </i> llavors la gràfica té concavitat negativa localment i per tant x=a és un màxim relatiu<br><b>Atenció</b>: si <i>f ″(a) = 0</i>, llavors no et permet concloure res, i et recomano estudiar el signe de <i>f ′(x)</i> a banda i banda del punt <i>x=a</i>.',
  'u9/51': 'Una funció que <b>sempre</b> és creixent implica que la funció derivada és sempre positiva, per a qualsevol valor <i>x</i>.<br>Per tant, has de derivar la funció. Obtindràs un polinomi de segon grau, és a dir, que la gràfica és una paràbola.<br>Per tal que una paràbola sigui sempre positiva, han de passar dues coses:<br>- No ha de tallar l\'eix d\'abscisses: ho veuràs amb el discriminant, que serà negatiu.<br>- Ha de tenir concavitat positiva, o sigui, obrir-se cap amunt. Ho veuràs amb el signe del coeficient de <i>x²</i>, que serà positiu.',
  'u9/58': 'En primer lloc, un extrem relatiu en <i>x = 2</i> vol dir que <i>y ′(2) = 0</i>. Calcula y \'(x) i quan escriguis la igualtat <i>y ′(2) = 0</i>, obtindràs una equació la incògnita <i>a</i>.<br>Un cop ja coneguis el valor de <i>a</i>, fes el mateix que a l\'exercici 42 per estudiar la monotonia: recorda que has de buscar <b>tots</b> els punts crítics, i no només <i>x = 2</i>.',
  'u9/66': 'Fes el mateix raonament que a l\'exercici 39, però amb <i>f \'\'(x)</i>: els punts d\'inflexió els trobaràs a partir de resoldre l\'equació <i>f ″(x) = 0</i>. Si <i>f</i> és un polinomi de grau <i>n</i>, <i>f ″</i> és un polinomi de grau <i>n − 2</i>.<br>Comprova-ho amb la recta i la paràbola, tenint en compte que, a més d\'anul·lar-se, <i>f ″(x)</i> ha de canviar de signe perquè hi hagi un punt d\'inflexió.',
  'u9/67': 'En primer lloc, troba el domini de cada funció, parant atenció a les racionals, a les arrels i als logaritmes.<br>Després, calcula <i>f ″(x)</i> i estudia\'n el signe als intervals que determinen els punts on <i>f ″(x)</i> s\'anul·la i els punts que no són del domini: si <i>f ″(x)>0</i> és positiva la funció té concavitat positiva i si <i>f ″(x)<0</i>, té concavitat negativa .<br><br><b>Ampliació</b>: un punt que no és del domini pot separar dos trams de curvatura, però no pot ser un punt d\'inflexió. Saps per què?',
  'u9/70': 'Fes el mateix que a l\'exercici 30: en total, hauràs d\'obtenir <b>tres</b> equacions, una per cada condició. Aquest cop les has d\'escriure tu:<br>- Passar per l\'origen vol dir que el punt <i>(0, 0)</i> pertany a la gràfica.<br>- Un punt d\'inflexió és on canvia la curvatura, i això només pot passar on s\'anul·la la derivada segona.<br>- El pendent de la tangent en un punt és el valor de la derivada en aquell punt.<br><br>Per acabar, hauràs de resoldre el sistema d\'equacions que en surti.',
  'u9/77': 'Anomena <i>x</i> i <i>y</i> els catets del triangle rectangle. El que vols maximitzar és l\'àrea del triangle, és a dir, <i>x·y/2</i>. Per aconseguir que només tinguem una variable, aplica el teorema de Pitàgores.<br><b>Observació:</b> veuràs que et queda una funció per maximitzar que té una arrel quadrada. Sempre pots maximitzar la mateixa funció però <i>sense l\'arrel quadrada</i>. Saps per què funciona, aquest mètode?',
  'u9/79': 'Dibuixa el full: a dins hi ha la part escrita, de dimensions <i>x</i> i <i>y</i>, i al voltant hi ha els marges.<br>La superfície total del full es pot calcular d\'aquesta manera: (<i>x</i> més els marges laterals) <i>multiplicat per</i> (<i>y</i> més els marges de dalt i de baix), i aquesta superfície és la que volem minimitzar.<br><b>Observació</b>: al final, comprova que el que trobes és realment un mínim relatiu.',
  'u9/86': 'Anomenem el vèrtex del rectangle <i>V = (x, y)</i> les coordenades del vèrtex que és a la recta i escriu la superfície del rectangle com a base per altura. Així tens dues variables, però l\'equació de la recta les lliga: aïlla\'n una i et quedarà la superfície en funció d\'una sola variable.<br>Després, deriva la funció i resol l\'equació igualant a zero.<br>Finalment, per comprovar que el que has trobat és un màxim i no un mínim, fes servir la derivada segona.',
  'u9/87': 'Un punt qualsevol de la paràbola tindrà aquesta forma: <i>P = (x, x²)</i>. La distància d\'aquest punt al punt <i>Q = (0, 1)</i> el pots calcular fent servir el teorema de Pitàgores.<br>Et quedarà una funció que conté una arrel. El punt que fa mínima la distància <i>és el mateix</i> que en fa mínim la funció al quadrat, que no porta arrel i és molt més còmode de derivar: saps per què?<br><b>Observació</b>: l\'enunciat et demana «els punts», en plural: tingues en compte la simetria de la paràbola.',

  /* ── Unitat 10 · Representació de funcions ───────────────────────────── */
  'u10/37': 'El que et donen és la gràfica de la derivada <i>y = f ′(x)</i>, no la de <i>y = f(x)</i>: tota la informació sobre <i>f</i> l\'has de treure de com es comporta aquesta corba.<br>Per a la creixement, decreixement i els extrems relatius: mira on <i>f ′(x)</i> és positiva o negativa i on talla l\'eix d\'abscisses.<br>Per a la curvatura, treballa amb <i>f ″(x)</i>.',
  'u10/38': 'Comença pel que ja saps: dibuixa les dues asímptotes, <i>x = 1</i> i <i>y = x + 1</i>. Com que <i>x = 1</i> no és del domini, la gràfica no hi pot passar: hi haurà una branca a cada costat de la recta vertical.<br>Després, afegeix la resta de condicions de l\'enunciat (punts, creixement, extrems…) i comprova que, quan <i>x</i> va cap a −∞ i cap a +∞, la corba s\'apropa a l\'asímptota obliqua.<br><b>Atenció</b>: l\'enunciat és de resposta oberta, de manera que hi ha moltes gràfiques que ho compleixen.',
  'u10/41': 'Comença pel domini: el denominador s\'anul·la en dos valors de <i>x</i>, i en aquests punts la funció no existeix. Quins són?<br>Després, calcula si hi ha asímptotes horitzontals.<br>Estudia el creixement i decreixement, els extrems relatius.<br>Fes una petita taula de valors.',
  'u10/43': 'Per a cada funció, has de tenir en compte coses diferents.<br>- Racional: el denominador no pot ser 0.<br>- Radical d\'índex parell: el que hi ha a dins de l\'arrel ha de ser ≥ 0.<br>- Logarítmica: el que hi ha a dins ha de ser > 0.<br>- Exponencial: el seu domini són els nombres reals.<br>- Trigonomètrica: <i>sin x</i> i <i>cos x</i> tenen domini el conjunt dels nombres reals.<br><b>Atenció</b>: <i>tg x</i>, segons la seva definició, conté una divisió.',
  'u10/45': 'Estudia en primer lloc el domini, i després ja estudiaràs els punts de tall.<br>- Domini: un polinomi no té cap restricció, però en una racional el denominador no pot ser 0.<br>- Tall amb l\'eix d\'ordenades: calcula <i>f(0)</i>.<br>- Tall amb l\'eix d\'abscisses: resol l\'equació <i>f(x) = 0</i>. En una funció racional, això vol dir que s\'anul·li el numerador, però <b>alerta</b>: comprova que el valor trobat sigui del domini.',
  'u10/62': 'Per a cada polinomi, calcula per separat els límits quan <i>x</i> → +∞ i quan <i>x</i> → −∞: això et diu cap on se\'n va cada branca de la gràfica.<br>Quan calculem límits en l\'infinit, sempre <b>mana</b> el terme de grau més alt: fixa\'t si el grau del polinomi és parell o senar, i també fixa\'t si el coeficient líder és positiu o negatiu. Això et permetrà decidir si el límit és −∞ o +∞.<br>',
  'u10/63': 'Per a les asímptotes verticals, busca els valors de <i>x</i> que anul·len el denominador. En cas de trobar una indeterminació 0/0, has de simplificar l\'expressió prèviament. Calcula els límits laterals per decidir si hi ha asímptota.<br>Per als límits en l\'infinit, compara el grau del numerador amb el del denominador i mira en quin cas ets.',
  'u10/75': 'Per a cada funció, troba els seus punts crítics resolent l\'equació <i>f ′(x) = 0</i>.<br>A partir d\'aquests punts, obtindràs uns intervals.<br><b>Atenció</b>: troba el domini de cada funció, perquè els punts que no són del domini també separen intervals.',
  'u10/78': 'Troba el domini de <i>f(x)</i> i estudia el signe de <i>f ″(x)</i> als intervals que determinen els punts on <i>f ″(x)</i> s\'anul·la i afegeix els punts que no són del domini de <i>f(x)</i>.<br><b>Atenció</b>. Si obtens <i>f ″(a) = 0</i>, no vol dir que hi hagi un punt d\'inflexió. Per exemple, <i>f(x) = x⁴</i> i tenim que <i>f \'\'(0) = 0</i>, però en canvi no hi ha cap punt d\'inflexió a <i>x = 0</i>.',
  'u10/84': 'Com que són polinomis, dues parts de l\'estudi es simplifiquen: el domini és tot ℝ i no hi ha asímptotes, i només cal mirar les branques infinites (els límits quan <i>x</i> → −∞ i quan <i>x</i> → +∞).',
  'u10/88': 'Hauràs d\'obtenir <b>tres</b> equacions, una per cada condició, i les has d\'escriure tu:<br>- Un extrem relatiu en <i>x = 2</i>: què ha de valer <i>f \'(x)</i> en aquest punt?<br>- Un punt d\'inflexió en <i>x = 0</i>: què ha de valer <i>f \'\'(x)</i> en aquest punt?<br>- Passar pel punt <i>(1, −5)</i> vol dir que <i>f(1) = 5</i>.<br>Per acabar, hauràs de resoldre el sistema d\'equacions que en surti.',
  'u10/91': 'És una funció racional. Comença estudiant el seu domini.<br>Per calcular les asímptotes: compara el grau del numerador amb el del denominador. Quin tipus d\'asímptota t\'anuncia això?',
  'u10/100': 'Per començar, resol la inequació que surt d\'imposar que el que hi ha dins de l\'arrel sigui ≥ 0, i dibuixa només la part de la recta on la funció existeix.<br>Als extrems del domini la corba s\'acaba. Calcula el límit de la derivada quan <i>x</i> s\'hi acosta des de dins del domini: si no és finit, la tangent és vertical.<br><b>Atenció</b>: els límit quan <i>x</i> → −∞ no té sentit, perquè el domini de la funció és [2, +∞). Entens per què?',
  'u10/108': 'Estudia cada tros de la funció pel seu compte, però només dins del seu interval: un extrem, un tall o una asímptota que et surti fora de l\'interval de definició no compta.<br>Després, en cada punt on canvia la definició, comprova dues coses per separat:<br>- Continuïtat: els dos límits laterals han de coincidir amb el valor de la funció.<br>- Derivabilitat: les dues derivades laterals han de coincidir.<br><b>Ampliació</b>: que una funció sigui contínua en un punt no vol dir que hi sigui derivable. Per exemple, la funció valor absolut, <i>y = |x|</i> és contínua a <i>x = 0</i>, però no és derivable a <i>x = 0</i>.',
  'u10/123': 'Observa el denominador del quocient: <i>x² − 6x + 10</i>. Hi ha algun punt on s\'anul·la?<br>Per trobar els punts de tall de <i>f(x)</i> amb l\'eix d\'abscisses, iguala la funció a zero i comprova si l\'equació té solució. Si no en té, la funció té sempre el mateix signe: saps per què? (pensa en el teorema de Bolzano). Per saber quin és, calcula <i>f(0)</i>.<br>Per a la monotonia i els extrems, deriva com de costum.<br>La funció <i>f(x)</i> té una asímptota horitzontal d\'equació <i>y = 20</i>. Saps per què?',
  'u10/124': 'Atenció, en aquest cas la variable independent és el temps <i>t</i>.<br>- La temperatura inicial és <i>f(0)</i>.<br>- La temperatura a la llarga és el límit quan <i>t</i> tendeix a +∞.<br>- Els extrems relatius són els moments en què la peça canvia de tendència (de refredar-se a escalfar-se, o al revés).<br>Atenció: tingues en compte que valors negatius no tenen sentit, perquè estem parlant del temps.',

  /* ── Unitat 11 · Integrals ───────────────────────────────────────────── */
  'u11/52': 'Recorda: la funció primitiva de <i>xⁿ</i> és <i>xⁿ⁺¹/(n+1)</i>.<br>Atenció: si observes algun producte de parèntesis, és recomanable desenvolupar-lo aplicant la propietat distributiva, abans d\'integrar.<br>Com que la integral indefinida és una família de primitives, el resultat sempre porta una constant <i>C</i>.',
  'u11/54': 'Et donem dues indicacions:<br>- Si el denominador és una potència <i>(x − a)ⁿ</i> amb <i>n</i> més gran que 1, escriu-la com a potència d\'exponent negatiu, <i>(x − a)⁻ⁿ</i>, i integra-la com qualsevol altra potència.<br>- Si el denominador és <i>x − a</i>, la primitiva és un <b>logaritme</b>, <i>ln|x − a|</i>. <b>Atenció</b>, fixa\'t que cal posar un valor absolut. Saps per què?',

  /* ── Unitat 12 · La integral definida ────────────────────────────────── */
  'u12/35': 'La integral definida entre <i>a</i> i <i>b</i> d\'una funció positiva és l\'àrea que queda entre la gràfica i l\'eix d\'abscisses.<br>Divideix cada regió en figures conegudes (triangles, rectangles, trapezis) i suma\'n les àrees.<br><b>Recorda</b>: si una part de la gràfica queda per sota de l\'eix d\'abscisses, la seva integral és negativa.',
  'u12/39': 'Escriu cada integral a partir de les que ja coneixes. Després, aplica les propietats següents:<br>- <b>Linealitat</b>: la integral de <i>k·f + g</i> és <i>k</i> per la integral de <i>f</i> més la integral de <i>g</i>.<br>- <b>Additivitat</b>: la integral entre <i>a</i> i <i>c</i> és la suma de la integral entre <i>a</i> i <i>b</i> i la integral entre <i>b</i> i <i>c</i>.<br>',
  'u12/55': 'Per a cada integral definida, busca una primitiva <i>F(x)</i> amb les integrals immediates i aplica la <b>regla de Barrow</b>: la integral entre <i>a</i> i <i>b</i> és <i>F(b) − F(a)</i>.<br>Pots triar qualsevol primitiva, ja que qualsevol constant <i>C</i> que escullis finalment s\'anul·larà. Saps per què?<br>',
  'u12/79': 'Una corba i l\'eix d\'abscisses tanquen una regió entre els punts on <i>f(x) = 0</i>. Resol aquesta equació: les solucions són, <b>precisament</b>, els límits d\'integració.<br>- Si només hi ha dos punts de tall, hi ha una sola regió.<br>- Si hi ha tres punts de tall: hi ha dues regions diferents, que has de tractar per separat.<br>Una part de la corba per sota de l\'eix dona una integral negativa, però per calcular l\'àrea hem de considerar el valor absolut de cadascuna de les parts.',
  'u12/80': 'El domini de la funció <i>f(x)</i> és <i>x ≥ 3</i> i, en <i>x = 3</i>, la funció val <i>0</i>: aquest és l\'extrem esquerre de la regió. L\'altre extrem el marca la recta vertical <i>x = 4</i>.<br>Per trobar la primitiva <i>F(x)</i>, et recomanem escriure l\'arrel com a potència, <i>(x − 3)^(1/2)</i>, i integrar-la com faries amb un polinomi.',
  'u12/88': '<i>a)</i> Comença pel domini: l\'arrel només existeix si <i>x ≥ 0</i>.<br>Calcula els punts de tall amb els eixos de coordenades.<br>Estudia el creixement o decreixement, resolent en primer lloc <i>f ′(x)=0</i>.<br><br><i>b)</i> Els límits d\'integració són els punts on la corba talla l\'eix d\'abscisses. Per integrar, escriu l\'arrel quadrada com a potència, <i>x^(1/2)</i>.',
  'u12/96': 'Un punt per on passa la recta tangent és <i>P = (1/2, f(1/2))</i> i el seu pendent val <i>f ′(1/2)</i>.<br>Et recomanem dibuixar en un mateix gràfic la paràbola, la recta tangent i l\'eix d\'ordenades: així veuràs la regió que queda tancada.<br>Els límits d\'integració són <i>x = 0</i> (l\'eix d\'ordenades) i l\'abscissa del punt de tangència, que és <i>P</i>.<br>Has d\'integrar la diferència entre una funció i l\'altra, i no oblidis prendre finalment el valor absolut.',
  'u12/111': 'Dues corbes tanquen un recinte entre els punts on es tallen, és a dir, on les dues funcions valen el mateix. Per tant, en primer lloc has de resoldre l\'equació <i>f(x) = g(x)</i>. Les solucions que obtinguis són els límits d\'integració.<br><b>Atenció</b>: una àrea mai no és negativa. Per aquest motiu calculem sempre el valor absolut de la integral definida.',
  'u12/114': 'Iguala les dues funcions i resol l\'equació que en resulta, per poder trobar <b>tots</b> els punts de tall: seran els límits d\'integració.<br>- Si només hi ha dos punts de tall, hi ha una sola regió.<br>- Si n\'hi ha tres, hi ha dues regions diferents, que has de tractar per separat: la funció que queda per sobre no és la mateixa a les dues.<br><b>Reflexió</b>: saps per què no pots integrar directament la diferència d\'un extrem a l\'altre?',

  /* ── Unitat 13 · Probabilitat ────────────────────────────────────────── */
  'u13/28': 'L\'<b>espai mostral</b> és el conjunt de tots els resultats possibles. Aquí cada resultat és una parella: el que surt a la moneda i el que surt al dau, per exemple <i>(cara, 3)</i>.<br>Organitza\'ls en una taula de doble entrada o en un diagrama d\'arbre.<br>',
  'u13/29': 'Fes el mateix que a l\'exercici 28: cada resultat és una parella formada pel color del llapis i la cara de la moneda.<br>Dibuixa un diagrama d\'arbre: per començar, desplega una branca per cada color; després, cada branca tindrà les dues possibilitats que obtenim amb la moneda.<br>',
  'u13/32': '«No patir cap de les dues malalties» és l\'esdeveniment <b>contrari</b> de «patir-ne almenys una», és a dir, de l\'esdeveniment <i>A∪B</i>.<br>Calcula primer <i>P(A∪B)</i>, tenint en compte que les persones que pateixen les dues malalties no les has de comptar dues vegades.<br>Finalment, calcula la probabilitat que et demanen.',
  'u13/33': 'Aplica la <b>regla de Laplace</b>: casos favorables dividit entre casos possibles.<br>A la taula de doble entrada, els casos favorables són els de la casella que creua «noi» amb «natació»; els casos possibles són totes les persones de la taula.<br><br><b>Atenció</b>: no és el mateix «ser noi i anar a natació» que «anar a natació, sabent que és noi». En el segon cas, es tracta de probabilitat condicionada. Saps què és?',
  'u13/35': 'El resultat de la moneda decideix de quin estoig es treu el bolígraf.<br>Dibuixa un diagrama d\'arbre (a la primera etapa, la moneda; a la segona, el color del bolígraf) i calcula la <b>probabilitat total</b> de treure negre:<br>- Dins de cada camí, multiplica les probabilitats de les branques.<br>- Entre els camins que acaben en negre, suma els resultats.<br>',
  'u13/36': 'Ara ja saps que el bolígraf és negre i vols saber de quin estoig ve: això s\'anomena <b>probabilitat condicionada</b>:<br><i>P(E₂/N)</i> (amb <i>N</i> = «bolígraf negre»), que es calcula amb el <b>teorema de Bayes</b>.<br>Al numerador, el camí de l\'arbre que passa per <i>E₂</i> i acaba en negre; al denominador, la probabilitat total de treure negre, que ja vas calcular a l\'exercici 35.<br>',
  'u13/40': 'Abans de comptar, respon dues preguntes a cada situació:<br>- És important o rellevant l\'ordre en què surten els elements?<br>- Està permès repetir els elements?<br>Amb les dues respostes sabràs quina situació pertoca aplicar: - una variació (amb repetició, o sense repetició) - una permutació<br>- una combinació<br>',
  'u13/60': 'Dos esdeveniments <i>A</i> i <i>B</i> són <b>independents</b> quan el fet de saber que ha ocorregut <i>A</i> no canvia la probabilitat de <i>B</i>. Això es tradueix en la igualtat següent:<br><i>P(A∩B) = P(A)·P(B)</i>.<br>Per decidir si dos esdeveniments són independents, pots calcular <i>P(A)</i>, <i>P(B)</i> i <i>P(A∩B)</i> a partir de les dades de l\'enunciat i comprovar si la igualtat es compleix.<br>',
  'u13/62': 'Defineix els dos esdeveniments següents:<br>- <i>X</i> = «s\'informa per les xarxes socials»<br>- <i>T</i> = «s\'informa pels telenotícies».<br>Dibuixa un diagrama de Venn i omple\'l amb les dades de l\'enunciat, començant per la zona on es creuen les dues fonts.<br>Cada probabilitat que et demanin és la suma de les zones que hi corresponguin. <b>Observació</b>: saps per quin motiu si vols calcular <i>P(X∪T)</i> no pots sumar directament <i>P(X)+P(T)</i>?',
  'u13/96': 'Si cada alumne pertany a una sola categoria, les tres categories reparteixen tots els alumnes sense solapar-se: això et permet dibuixar un diagrama d\'arbre, amb les tres categories a la primera etapa.<br>Per als dos tipus d\'apartat, tingues en compte això:<br>- Probabilitat total: suma el camí que passa per cadascuna de les tres categories.<br>- Probabilitat condicionada: <i>P(A/B)</i> és la probabilitat d\'<i>A</i> sabent que ja ha passat <i>B</i>. Fixa\'t bé en quina de les dues dades és la que ja se sap.<br>',
  'u13/103': 'Calcula primer <i>P(A∪B)</i> amb la fórmula que inclou <i>P(A∩B)</i> i, després, passa a la probabilitat de l\'esdeveniment contrari.<br>Entens per què, en la fórmula de la unió, cal restar <i>P(A∩B)</i>?',
  'u13/104': 'Defineix:<br>- <i>E</i> = «fa esport»<br>- <i>I</i> = «toca un instrument».<br>Per calcular l\'esdeveniment «cap de les dues activitats» calcula primer la probabilitat de fer-ne alguna, <i>P(E∪I)</i>, i després passa a calcular l\'esdeveniment contrari.<br>Quins estudiants formen la intersecció <i>E∩I</i>? Recorda que només els has de comptar una vegada.',
  'u13/105': 'El primer apartat és directe: aplica la fórmula de la probabilitat de la unió.<br>El segon apartat: els esdeveniments són «passa <i>A</i> però no passa <i>B</i>», i «passa <i>B</i> però no passa <i>A</i>». Dibuixa un diagrama de Venn i pinta aquestes dues zones.<br>Mira el dibuix: com pots obtenir la suma de les dues zones a partir de <i>A∪B</i> i <i>A∩B</i>?',
  'u13/106': 'Defineix els esdeveniments: <i>S</i> = «utilitza energia solar» i <i>E</i> = «utilitza energia eòlica».<br>Organitza les dades de l\'enunciat en una taula de doble entrada, o bé en un diagrama de Venn.<br>',
  'u13/107': 'Dibuixa un diagrama d\'arbre.<br>- Per a calcular <i>P(B)</i>: hi ha dos camins que acaben en <i>B</i>, el que passa per <i>A</i> i el que passa per l\'esdeveniment contrari a <i>A</i>. Multiplica les branques de cada camí i suma els dos resultats (<b>probabilitat total</b>).<br>- Per a <i>P(A/B)</i>: aplica el <b>teorema de Bayes</b>, amb el camí que passa per <i>A</i> i acaba en <i>B</i> al numerador i <i>P(B)</i> al denominador.',
  'u13/108': 'Comença ordenant les dades de l\'enunciat:<br>- quina proporció de persones fa dieta?<br>- quina proporció practica esport?<br>- quina proporció correspon a les que fan les dues coses?<br>Amb això, pots omplir una taula de doble entrada (dieta / esport) i cada apartat és llegir la casella o la fila que toca.<br><br><b>Atenció</b>: una probabilitat condicionada, com «de les que fan dieta, quines practiquen esport?», no és una casella de la taula, sinó una casella dividida pel total de la seva fila. Saps per què?',

  /* ── Unitat 14 · Distribucions de probabilitat ───────────────────────── */
  'u14/21': 'Anomenem <i>X</i> = «nombre d\'adolescents amb gingivitis»: cada adolescent en té o no en té, amb la mateixa probabilitat per a tots, i el que li passa a un no influeix en els altres.<br>Per tant, tenim una <b>distribució binomial</b>, <i>B(n; p)</i>, i només has de deduir <i>n</i> i <i>p</i> a l\'enunciat.<br><br>Per a la mitjana i la variància no cal sumar res: la binomial té fórmules pròpies, que només depenen de <i>n</i>, <i>p</i> i <i>q</i> = 1 − <i>p</i>.<br>',
  'u14/43': 'No cal fer cap càlcul. Una variable és <b>binomial</b> quan l\'experiment compleix aquestes quatre condicions alhora:<br>1- El nombre de repeticions està fixat.<br>2- A cada repetició només hi ha dos resultats possibles: èxit o fracàs.<br>3- La probabilitat d\'èxit és la mateixa a totes les repeticions.<br>4- Les repeticions són independents: un resultat no afecta els altres.<br>Comprova-les una per una a cada variable: si en falla com a mínim una, ja no és distribució binomial.<br><br>',
  'u14/44': 'Identifica <i>n</i> i <i>p</i> a <i>B(4; 0,25)</i>.<br>Com que <i>X</i> compta els èxits en 4 repeticions, pot valer 0, 1, 2, 3 o 4: calcula <i>P(X = k)</i> per a cadascun d\'aquests valors amb la fórmula de la binomial.<br>El número combinatori de cada terme compta de quantes maneres poden sortir els <i>k</i> èxits dins de les 4 repeticions: és el mateix que feies amb les combinacions a la unitat 13.<br>Quan tinguis la taula feta, suma totes les probabilitats: saps per què la suma total dona exactament 1?',
  'u14/46': 'Abans de res, comprova que la situació compleix les condicions per tenir una distribució binomial. Després, per a cada situació identifica aquestes dues dades:<br>- <i>n</i>: quantes vegades es repeteix l\'experiment?<br>- <i>p</i>: quina és la probabilitat d\'èxit en una sola repetició?<br><br><b>Observació</b>: quan diem «èxit», no volem dir «bon resultat», sinó que ens referim al fet que la variable està comptant. Per exemple, si la variable compta peces defectuoses, l\'èxit seria «ser defectuosa».',
  'u14/50': 'Comença identificant <i>n</i> i <i>p</i>: aquí <i>X</i> = «nombre de piles descarregades» i hi ha 12 piles. Et demanen <i>P(X > 2)</i>.<br>«Més de 2» vol dir 3, 4, 5, 6... fins a 12: si ho calcules directament, és un càlcul molt llarg.<br>Surt més a compte calcular l\'<b>esdeveniment contrari</b>: és «2 o menys», que només implica calcular tres termes (0, 1 i 2).<br>Quan tinguis la probabilitat del contrari, saps com obtens la que et demanen?',
  'u14/53': 'Identifica, en primer lloc:<br><i>n</i>: (nombre d\'enquestats)<br><i>p</i>: (probabilitat que un enquestat respongui «NS/NC»)<br><br><i>X</i> = «nombre d\'enquestats que responen NS/NC» és una distribució binomial.<br>Els dos apartats no es resolen igual:<br>- «Exactament 3» és <i>P(X = 3)</i>: un sol terme de la fórmula.<br>- «Com a mínim 10» és <i>P(X ≥ 10)</i>: vol dir 10, 11, 12... fins a <i>n</i>.',
  'u14/100': 'Fixa\'t que 10 és el valor més alt que pot prendre <i>X</i> a <i>B(10; 0,9)</i>:<br>- <i>P(X = 10)</i>: els 10 casos han de ser èxit alhora. De quantes maneres pot passar? Això et diu quant val el número combinatori.<br>- <i>P(X > 1)</i>: «més d\'1» vol dir 2, 3... fins a 10, o sigui nou càlculs. És preferible treballar amb l\'esdeveniment contrari.',
  'u14/101': 'Tenim una distribució <i>B(10; 0,9)</i>. Abans de calcular, fes la traducció:<br>- Cada article és una repetició.<br>- L\'«èxit» és que l\'article no tingui defecte.<br>- <i>X</i> = «nombre d\'articles sense defecte».<br>Llavors escriu cada pregunta de l\'enunciat amb la notació de <i>X</i>: per exemple, «exactament 8 articles sense defecte» és <i>P(X = 8)</i>.<br>Quins dels càlculs de l\'exercici 100 pots reaprofitar?',
};


/* ═══════════════════════════════════════════════════════════════════════
   A PARTIR D'AQUÍ NO CAL QUE TOQUIS RES
   ═══════════════════════════════════════════════════════════════════════ */

/* La pista d'un exercici, o null si no en té. */
function pistaDe(u, n){
  const t = PISTES[u + '/' + n];
  return t ? t : null;
}

/* Quants dels exercicis d'una llista de refs {u,n} tenen pista.
   DESACTIVADA: ara mateix no la crida cap pàgina. Es deixa comentada
   per si algun dia es vol mostrar "N pistes" a la llista de tasques.

function comptaPistes(refs){
  let k = 0;
  refs.forEach(r => { if(pistaDe(r.u, r.n)) k++; });
  return k;
}
*/
